import type {TagOption} from '../types';

export const getTagsValues = <ValueType>(values?: TagOption<ValueType>[], maxTagCount?: number) => {
    if (!values || !maxTagCount) {
        return {
            tags: values ?? [],
            remainingTagOption: undefined,
        };
    }

    let countRemainingTags;
    let tags = values;

    if (maxTagCount > 0) {
        countRemainingTags = Math.max(values.length - maxTagCount, 0);

        if (countRemainingTags > 0) {
            tags = values.slice(0, maxTagCount);
        }
    }

    const remainingTagOption = countRemainingTags
        ? {
              value: -1,
              content: `+ ${countRemainingTags}`,
          }
        : undefined;

    return {tags, remainingTagOption};
};
